import React, { useState, useEffect } from "react";
import { NavLink } from "react-router-dom"; 
import "./NavBar.css";
import { FaHome, FaColumns, FaBook, FaInfoCircle } from "react-icons/fa";
import { useLocation } from 'react-router-dom';
import Modal from 'react-modal';

const pageMapping = {
    '/': 'home',
    '/dashboard': 'dashboard',
    '/library':'library',
    '/aboutus':'aboutus'
};
const customStyles = {
    content: {
    top: '50%',
    left: '50%',
    right: 'auto',
    bottom: 'auto',
    marginRight: '-50%',
    transform: 'translate(-50%, -50%)',
    borderRadius: '8px', 
    width:'430px'// Added border radius
    },
};

function NavBar() {
    const { pathname } = useLocation();
    const currentPage = pageMapping[pathname] || '';

    const [activeLink, setActiveLink] = useState(currentPage);
    const [modalSignInIsOpen, setSignInIsOpen] = useState(false);
    const [modalSignUpIsOpen, setSignUpIsOpen] = useState(false);
    const [user, setUser] = useState();

    const handleLinkClick = (link) => {
        setActiveLink(link);
    };
// opens the signup modal
  function openSignInModal() {
    setSignUpIsOpen(false);
    setSignInIsOpen(true);
  }
// closes the signup modal or the login modal
  function closeSignInModal() {
    if (modalSignUpIsOpen) {
        setSignUpIsOpen(false);
    }else{
        setSignInIsOpen(false);
    }
  }

  function login(event) {
    event.preventDefault(); // Prevent the default form submission
    console.log("Login clicked");
    setUser({ name: "User" });
    setSignInIsOpen(false);
  }
  function logout() {
    console.log("Logout clicked");
    setUser(null);
  }

    useEffect(() => {
        setActiveLink(currentPage);
    }, [currentPage]);

    return (
        <nav className="navbar">
            <div className="logo" onClick={() => window.location.href = "/"}>
                <img src="/Jaguar-Head-Maroon-White.png" alt="JagCoach Logo" className="nav-logo" />
                <span className="nav-text">JagCoach</span>
            </div>
            <ul className="nav-links">
                <li className={activeLink === "home" ? 'active-empty' : 'empty-div'}>
                    <div className={activeLink === "home" ? 'active-empty-div' : ''}>.</div>
                </li>
                <li>
                    <NavLink 
                        to="/" 
                        className={activeLink === "home" ? 'active' : ''}
                        onClick={() => handleLinkClick("home")}
                    ><FaHome />
                        <span className="nav-text">Home</span>
                    </NavLink>
                </li>
                 <li className={activeLink === "dashboard" ||activeLink === "home"? 'active-empty' : 'empty'} > <div className={activeLink === "dashboard" ? 'active-empty-div' : 'empty-div'} >.</div> </li>
                <li>
                    <NavLink 
                        to="/dashboard" 
                        className={activeLink === "dashboard" ? 'active' : ''}
                        onClick={() => handleLinkClick("dashboard")}
                    ><FaColumns /> 
                       <span className="nav-text">Dashboard</span>
                    </NavLink>
                </li>
               {user&&(<>                <li className={activeLink === "dashboard"||activeLink === "library"? 'active-empty' : 'empty'}> <div  className={activeLink === "library"? 'active-empty-div' : 'empty-div'}>.</div> </li>
<li>
                    <NavLink 
                        to="/library" 
                        className={activeLink === "library" ? 'active' : ''}
                        onClick={() => handleLinkClick("library")}
                    ><FaBook />
                        <span className="nav-text">Library</span>
                    </NavLink>
                </li> 

                </>)}
                {user?(<li className={activeLink === "aboutus"||activeLink === "library"? 'active-empty' : 'empty'}> <div className={activeLink === "aboutus" ? 'active-empty-div' : 'empty-div'} >.</div> </li>):(<li className={activeLink === "aboutus"||activeLink === "library"||activeLink === "dashboard"? 'active-empty' : 'empty'}> <div className={activeLink === "aboutus" ? 'active-empty-div' : 'empty-div'} >.</div> </li>)}


                <li>
                    <NavLink 
                        to="/aboutus" 
                        className={activeLink === "aboutus" ? 'active' : ''}
                        onClick={() => handleLinkClick("aboutus")}
                    ><FaInfoCircle />
                       <span className="nav-text">About Us</span>
                    </NavLink>
                </li>
                <li className={activeLink === "aboutus"? 'active-empty' : ''}>
                    <div className={activeLink === "aboutus" ? 'empty-div' : 'empty'} >.</div>
                </li>
            </ul>

            <div className="logout-button-div">
                <button className="login-button" onClick={user ? () => logout() : openSignInModal}>{user ? 'Logout' : 'Login'}</button>
                <Modal
                    isOpen={modalSignInIsOpen}

                    onRequestClose={closeSignInModal}
                    style={customStyles}
                    contentLabel="Login Modal"

                >
                <div>
                    <div className="login-header">
                    <h2 >{modalSignUpIsOpen?'Sign Up':'Sign In'}</h2>
                    <button onClick={closeSignInModal}>ⅹ</button>
                    </div>
                    {modalSignUpIsOpen?(<form className="login-form">
                        <label htmlFor="name">Name</label>
                        <input type="text" id="name" placeholder="Full Name" required />

                        <label htmlFor="email">Email</label>
                        <input type="email" id="email" placeholder="your@email.com" required />
                        <label htmlFor="password">Password</label>
                        <input type="password" id="password" placeholder="Password" required />
                        <button type="submit">Sign Up</button>
                    </form>):( <div>
                    <form className="login-form" onSubmit={login}>

                        <label htmlFor="email">Email</label>
                        <input type="email" id="email" placeholder="your@email.com" required />
                        <label htmlFor="password">Password</label>
                        <input type="password" id="password" placeholder="Password" required />
                        <button type="submit">Login</button>
                    </form>
                    <p>Don't have an account? <span className="signup-link" style={{ textDecoration: 'underline' }} onClick={() => setSignUpIsOpen(true)}>Sign Up</span></p>
                      </div> )}
                    </div>
                </Modal>
            </div>
        </nav>
    );
}

export default NavBar;
